// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DnGmxBatchingManager} from "../src/DnGmxBatchingManager.sol";

contract InvMutTest is Test {
    DnGmxBatchingManager c;
    function setUp() public { c = new DnGmxBatchingManager(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(caller != address(this));
        vm.assume(caller != c.owner());
        vm.assume(newOwner != address(0));
        vm.assume(caller != newOwner);

        vm.prank(caller);
        try c.transferOwnership(newOwner) {} catch {}

        assertTrue(c.owner() != newOwner || caller == c.owner() || caller == address(0));
    }
}
